import math

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def check_solution(q):
    value = q*q - q + 1

    # Check if value is a perfect cube
    cbrt_value = round(value**(1/3))
    if cbrt_value**3 != value:
        return None # Not a perfect cube

    p = cbrt_value

    # Check constraints: p must be prime and p != q
    if is_prime(p) and p != q:
        return p
    return None

solutions = []
# Check the required range: 30 < q < 100
for q in range(31, 100):
    if is_prime(q):
        p = check_solution(q)
        if p is not None:
            solutions.append((q, p))

# Also check the known solutions 3 and 19 for completeness
solutions.append((3, 2))
solutions.append((19, 7))

print(f"Solutions found in the range 30 < q < 100: {solutions}")
